(function(){
'use strict';
const $=id=>document.getElementById(id);let previewUrl;
function row(description='',quantity=1,price=''){return `<div class="document-item"><input data-item-description required aria-label="Deliverable description" placeholder="Deliverable" value="${escapeHtml(description)}"><input data-item-quantity type="number" min="0.01" step="any" required aria-label="Quantity" value="${quantity}"><input data-item-price type="number" min="0" step="0.01" required aria-label="Unit price" value="${price}"><button type="button" data-remove-item aria-label="Remove item">×</button></div>`;}
for(const type of ['quote','invoice']){
 const form=$(type+'-form');form.elements.amount.readOnly=true;form.elements.amount.step='0.01';
 form.querySelector('.form-grid').insertAdjacentHTML('beforeend',`<label class="field"><span>Currency</span><select name="currency"><option>MWK</option></select></label><label class="field"><span>Prepared by</span><input name="preparedBy" required></label><div class="field field-wide"><span>Deliverable · Quantity · Unit price</span><div class="document-items">${row()}</div><button type="button" data-add-document-item>Add line item</button></div><label class="field field-wide"><span>Service description (one point per line)</span><textarea name="serviceDetails" rows="4"></textarea></label><label class="field field-wide"><span>Payment details</span><textarea name="paymentDetails" rows="4">CAGE\n1013608314\nGateway Mall Branch\nNational Bank</textarea></label>`);
 form.querySelector('.dialog-actions').insertAdjacentHTML('afterbegin','<button type="button" class="secondary-button" data-preview-document>Preview PDF</button>');
 form.addEventListener('reset',()=>setTimeout(()=>{form.querySelector('.document-items').innerHTML=row();form.elements.preparedBy.value=window.CAGE_BACKEND.currentProfile()?.full_name||'CAGE';},0));
 form.addEventListener('input',()=>{const total=[...form.querySelectorAll('.document-item')].reduce((sum,r)=>sum+Math.round(Number(r.querySelector('[data-item-quantity]').value)*Number(r.querySelector('[data-item-price]').value)*100)/100,0);form.elements.amount.value=total||'';});
 form.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-add-document-item'))form.querySelector('.document-items').insertAdjacentHTML('beforeend',row());if(b.hasAttribute('data-remove-item')&&form.querySelectorAll('.document-item').length>1){b.closest('.document-item').remove();form.dispatchEvent(new Event('input'));}if(b.hasAttribute('data-preview-document')){try{await preview({...Object.fromEntries(new FormData(form)),...fields(form),number:'PREVIEW'},type);}catch(error){$(type+'-form-error').textContent=error.message;}}});
}
$('send-document-preview').insertAdjacentHTML('afterend','<button type="button" class="secondary-button" id="preview-send-pdf">Preview attached PDF</button>');
$('preview-send-pdf').onclick=async()=>{try{const type=$('send-form').elements.documentType.value,id=$('send-form').elements.documentId.value;await preview((type==='quote'?state.quotes:state.invoices).find(r=>r.id===id),type);}catch(e){$('send-form-error').textContent=e.message;}};
document.body.insertAdjacentHTML('beforeend','<dialog id="pdf-preview-dialog" class="app-dialog pdf-preview-dialog"><div class="dialog-heading"><h2>Document preview</h2><button type="button" id="close-pdf-preview">Close</button></div><a id="download-document-pdf" class="primary-button" download>Download PDF</a><iframe id="document-pdf-frame" title="Quotation or invoice PDF preview"></iframe></dialog>');
$('close-pdf-preview').onclick=()=>{$('pdf-preview-dialog').close();if(previewUrl)URL.revokeObjectURL(previewUrl);};
function fields(form){
 const items=[...form.querySelectorAll('.document-item')].map(r=>({description:r.querySelector('[data-item-description]').value.trim(),quantity:Number(r.querySelector('[data-item-quantity]').value),unitPrice:Number(r.querySelector('[data-item-price]').value)}));
 if(!items.length||items.some(i=>!i.description||!Number.isFinite(i.quantity)||i.quantity<=0||!Number.isFinite(i.unitPrice)||i.unitPrice<0))throw new Error('Complete each deliverable, quantity and unit price.');
 return {items,currency:form.elements.currency.value,preparedBy:form.elements.preparedBy.value,serviceDetails:form.elements.serviceDetails.value,paymentDetails:form.elements.paymentDetails.value,amount:items.reduce((sum,i)=>sum+Math.round(i.quantity*i.unitPrice*100)/100,0)};
}
async function preview(record,type){const logo=await(await fetch('./cage-logo-new.png')).arrayBuffer();const bytes=await CagePDF.createDocumentPDF(PDFLib,record,type,logo);if(previewUrl)URL.revokeObjectURL(previewUrl);previewUrl=URL.createObjectURL(new Blob([bytes],{type:'application/pdf'}));$('document-pdf-frame').src=previewUrl;$('download-document-pdf').href=previewUrl;$('download-document-pdf').download=`${record.number}.pdf`;$('pdf-preview-dialog').showModal();}
window.CAGE_DOCUMENTS={fields,preview};
})();
